<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Pembiayaan extends Model {protected $table='pembiayaan'; protected $fillable=['tahun_anggaran_id','jenis','kode','uraian','anggaran','urutan','status_publikasi']; protected $casts=['anggaran'=>'decimal:2']; public function realisasi(){return $this->hasMany(RealisasiPembiayaan::class);} public function scopePublik($q){return $q->where('status_publikasi','dipublikasikan');}}
